import heapq
from collections import defaultdict

def dijkstra(graph, src):
    dist = {v: float("inf") for v in graph}
    dist[src] = 0
    pq = [(0, src)]
    while pq:
        d, u = heapq.heappop(pq)
        if d > dist[u]:
            continue
        for v, w in graph[u]:
            nd = d + w
            if nd < dist[v]:
                dist[v] = nd
                heapq.heappush(pq, (nd, v))
    return dist

def build(edges):
    g = defaultdict(list)
    for a, b, w in edges:
        g[a].append((b, w)); g[b].append((a, w))
    return g

if __name__ == "__main__":
    g = build([(0, 1, 4), (0, 2, 1), (2, 1, 2), (1, 3, 1), (2, 3, 5)])
    print({k: v for k, v in dijkstra(g, 0).items()})
```
The loop pops the smallest tentative distance, skips stale entries, and relaxes every outgoing edge, so the result is {0: 0, 1: 3, 2: 1, 3: 4}.

